var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var r=root.GetComponent<Character.Control.PaddleCharacterVisual>();float drift=0,maxGap=0;UnityEngine.Vector3 baseL=UnityEngine.Vector3.zero,baseR=UnityEngine.Vector3.zero;
 for(int i=0;i<1080;i++){
  float reach=new[]{.75f,1.35f,1.975f}[i/360];var q=UnityEngine.Quaternion.Euler(0,0,i%360);r.tool.rotation=q;r.tool.position=r.body.position+q*new UnityEngine.Vector3(reach,.074f,0);r.Pose();
  var l=r.paddle.transform.InverseTransformPoint(r.LeftHand);var rr=r.paddle.transform.InverseTransformPoint(r.RightHand);
  if(i==0){baseL=l;baseR=rr;}else drift=UnityEngine.Mathf.Max(drift,UnityEngine.Vector3.Distance(l,baseL),UnityEngine.Vector3.Distance(rr,baseR));
  var lower=root.GetComponentsInChildren<UnityEngine.SpriteRenderer>().First(x=>x.name=="Forearm segment "+r.rightLower.name);
  var a=Character.Control.PaddleCharacterVisual.PixelPosition(r.rightUpper,new UnityEngine.Vector2(12,74));var b=Character.Control.PaddleCharacterVisual.PixelPosition(lower,new UnityEngine.Vector2(12,28));maxGap=UnityEngine.Mathf.Max(maxGap,UnityEngine.Vector3.Distance(a,b));
 }
 string log="1080 poses; paddle-local grip drift="+drift+" left="+baseL+" right="+baseR+" max right elbow anchor gap="+maxGap;
 System.IO.File.WriteAllText("scripts/player-locked-grips-20261111/fixed-grips.txt",log);UnityEngine.Debug.Log(log);
 if(drift>.00001f)throw new System.Exception("Grip moved on paddle");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
